/// <summary>
/// returns all booked hours for current resource and date
/// </summary>
/// <returns>Qty</returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVAHoursBooked avaDisplayBookedHours()
{
    ProjEmplTrans       projEmplTrans;
    DataArea            dataArea;
    ResourceView        resourceView;
    container           conCompanies;
    ResProjectResource  resProjResource;
    Counter             i = 1;

    select firstonly resProjResource where resProjResource.Resource == this.Resource;
    while select DataArea
        exists join resourceView where resourceView.ResourceCompanyId == dataArea.id
                            && resourceView.ResourceId == resProjResource.ResourceId
    {
        conIns(conCompanies,i,dataArea.id);
        i++;
    }

    select crosscompany : conCompanies sum(Qty) from projEmplTrans 
        where projEmplTrans.TransDate == this.ProjTransDate
        && projEmplTrans.Resource == this.Resource;

    /*select sum(qty) from projEmplTrans
        where projEmplTrans.TransDate == this.ProjTransDate
        && projEmplTrans.Resource == this.Resource; */

    return projEmplTrans.Qty;
}

/// <summary>
/// returns all unbooked hours for current resource and date
/// </summary>
/// <returns>Qty</returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVAHoursUnbooked avaDisplayUnbookedHours()
{
    ProjUnpostedTransView ProjUnpostedTransView;
    Qty qty;

    DataArea            dataArea;
    container           conCompanies;
    ResProjectResource  resProjResource;
    Counter             i = 1;
    ResourceView        resourceView;

    select firstonly resProjResource where resProjResource.Resource == this.Resource;
    while select DataArea
        exists join resourceView where resourceView.ResourceCompanyId == dataArea.id
                            && resourceView.ResourceId == resProjResource.ResourceId
    {
        conIns(conCompanies,i,dataArea.id);
        i++;
    }

    resourceView = resourceView::find(this.Resource);

    //while select ProjUnpostedTransView
    while select crosscompany : conCompanies ResourceName, qty from ProjUnpostedTransView
    where ProjUnpostedTransView.transtype == ProjTransType::Hour
        && ProjUnpostedTransView.transdate == this.ProjTransDate
    {
        if (ProjUnpostedTransView.ResourceName == resourceView.Name)
        {
            qty += ProjUnpostedTransView.Qty;
        }
    }
    return qty;
}

/// <summary>
/// returns all entered hours 
/// </summary>
/// <returns>Qty</returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVAHoursTotal avaDisplayTotalHours()
{
    return this.avaDisplayBookedHours() + this.avaDisplayUnbookedHours();
}

/// <summary>
/// AVA/WEN/2024/11/13      AVA_012426_HoursJournal
/// </summary>
/// <returns>smmActivityPurpose</returns>
[SysClientCacheDataMethodAttribute(true)]
public display smmActivityPurpose avaDisplayActivityPurpose()
{
    return smmActivities::find(this.ActivityNumber).Purpose;
}

/// <summary>
/// AVA/WEN/2025/03/04     AVA_013083_CategoryFromResource
/// </summary>
public void avaSetCategoryFromResource()
{
    if (this.Resource)
    {
        this.CategoryId = ResourceFacade::getDefaultTimeCategoryId(this.Resource);
    }
}
